    },
    {
      "type": "figure",
      "bbox_0_1": [0.337, 0.542, 0.58, 0.649],
      "confidence": 0.92,
      "caption": "图5.2.3",
      "image_alt": "振动盘支架安装方式示意图，传感器位置用圆圈和编号3标出。"
    },
